import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import net from 'node:net';
import { DatabaseSync } from 'node:sqlite';

test('priorities migrate existing tasks and persist independently across archive and restart', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-priorities-'));
  const databasePath = join(directory, 'workboard.sqlite');
  const database = new DatabaseSync(databasePath);
  database.exec(`
    CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0);
    CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0);
    INSERT INTO projects (name) VALUES ('First'), ('Second');
    INSERT INTO tasks (project_id, title, completed) VALUES (1, 'Existing done', 1), (1, 'Existing open', 0), (2, 'Other project', 0);
  `);
  database.close();
  const reservation = net.createServer();
  reservation.listen(0, '127.0.0.1');
  await once(reservation, 'listening');
  const port = reservation.address().port;
  await new Promise((resolve) => reservation.close(resolve));
  const base = `http://127.0.0.1:${port}`;
  let child;
  let output = '';
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      cwd: new URL('..', import.meta.url),
      env: { ...process.env, PORT: String(port), DB_PATH: databasePath },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    child.stderr.on('data', (chunk) => { output += chunk; });
    for (let attempt = 0; attempt < 100; attempt++) {
      if (child.exitCode !== null) throw new Error(`Server exited: ${output}`);
      try { if ((await fetch(`${base}/health`)).ok) return; } catch {}
      await new Promise((resolve) => setTimeout(resolve, 25));
    }
    throw new Error(`Server did not become healthy: ${output}`);
  }
  async function stop() {
    if (!child || child.exitCode !== null) return;
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
  }
  const get = async (path) => (await fetch(`${base}${path}`)).json();
  const write = (path, body, method = 'PATCH') => fetch(`${base}${path}`, {
    method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  });
  const tasksPath = '/api/projects/1/tasks';
  try {
    await start();
    const tasks = await get(tasksPath);
    assert.deepEqual(tasks, [
      { id: 1, title: 'Existing done', completed: true, priority: 'Normal' },
      { id: 2, title: 'Existing open', completed: false, priority: 'Normal' },
    ]);
    const otherTasks = await get('/api/projects/2/tasks');
    const created = await (await write(tasksPath, { title: 'New' }, 'POST')).json();
    assert.equal(created.priority, 'Normal');
    tasks.push(created);
    const summaries = await get('/api/projects');
    for (const priority of ['High', 'Low', 'Normal', 'High']) {
      const response = await write(`${tasksPath}/1`, { priority });
      assert.equal(response.status, 200);
      tasks[0].priority = priority;
      assert.deepEqual(await response.json(), tasks[0]);
      assert.deepEqual(await get(tasksPath), tasks);
      assert.deepEqual(await get('/api/projects/2/tasks'), otherTasks);
      assert.deepEqual(await get('/api/projects'), summaries);
    }
    for (const priority of ['', 'Urgent', 'high', null, 1]) {
      assert.equal((await write(`${tasksPath}/1`, { priority })).status, 400);
      assert.deepEqual(await get(tasksPath), tasks);
    }
    assert.equal((await write('/api/projects/2/tasks/1', { priority: 'Low' })).status, 404);
    await write(`${tasksPath}/1`, { title: '  Renamed  ' });
    tasks[0].title = 'Renamed';
    assert.deepEqual(await get(tasksPath), tasks);
    await write('/api/projects/1', { archived: true });
    assert.equal((await write(`${tasksPath}/1`, { priority: 'Low' })).status, 409);
    await stop();
    await start();
    assert.deepEqual(await get(tasksPath), tasks);
    assert.equal((await get('/api/projects/1')).archived, 1);
    await write('/api/projects/1', { archived: false });
    await write(`${tasksPath}/2`, { priority: 'Low' });
    tasks[1].priority = 'Low';
    await write(`${tasksPath}/1`, { completed: false });
    tasks[0].completed = false;
    await stop();
    await start();
    assert.deepEqual(await get(tasksPath), tasks);
    assert.deepEqual(await get('/api/projects/2/tasks'), otherTasks);
    assert.equal((await get('/api/projects/1')).completed, 0);
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});
# Workboard

Requires Node.js 22.22.1. Uses built-in HTTP and SQLite modules with no external dependencies.

Start the application:

```sh
PORT=8080 DB_PATH=./data/workboard.sqlite npm start
```

Open `http://localhost:8080`. Create a project and open it to create tasks, toggle completion, and filter by All, Open, or Completed. The project list shows completion summaries and filters Active or Archived projects. Archive projects to make their tasks read-only; restore them to resume editing. The server binds to `0.0.0.0`; `PORT` defaults to `8080` and `DB_PATH` defaults to `data/workboard.sqlite`. Keep the database file to preserve projects, tasks, completion, and archive state across restarts. Existing databases are upgraded automatically. `GET /health` returns `{"status":"ok"}`.

On an active project page, use New project name and Rename project to update its name. Names are trimmed and cannot be blank. Renaming preserves the URL, creation order, tasks, and completion summary. Archived projects disable renaming until restored. Renamed names persist in the same SQLite database.

Each task row has New task title and Rename task controls. Task renames trim whitespace and reject blank titles, preserving ownership, creation order, completion, filters, and project summaries. The completion checkbox label follows the saved title. Archived projects disable task renaming until restored; titles persist across reloads and restarts.

Each task also has a Task priority selector with Low, Normal, and High options. Existing and new tasks default to Normal. Priorities persist independently across reloads, restarts, and renames; archived projects disable priority edits until restored.

Run the integration checks:

```sh
npm test
```

Tests use a temporary SQLite database and verify schema migration, validation, creation order, project isolation, completion updates, archive/restore, summaries, the page and asset routes, and persistence across server restarts.
Tests also cover project and task renaming, unchanged identity and completion state, rejection of archived renames, and renaming after restoration.
UI event-handler checks use a minimal DOM adapter to verify validation, checkbox names, completion changes, filters, summaries, renaming, and archived controls without external dependencies.
Priority checks cover migration of existing tasks, independent saved values, invalid input, filters, renames, archived controls, restoration, and server restarts.
