  border-radius: 12px;
}
h1 { margin: 0 0 28px; font-size: 2rem; }
label { display: block; margin-bottom: 8px; font-weight: 600; }
.form-controls { display: flex; gap: 12px; }
input[type="text"], select {
  min-width: 0;
  flex: 1;
  border: 1px solid #8594aa;
  border-radius: 6px;
  padding: 10px 12px;
  font: inherit;
}
button {
  border: 1px solid #204ca4;
  border-radius: 6px;
  background: #204ca4;
  color: white;
  padding: 10px 16px;
  font: inherit;
  cursor: pointer;
}
button:hover { background: #173c85; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #739cee; outline-offset: 3px; }
#projects { margin-top: 28px; }
.project-row, .task-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 16px 0;
  border-top: 1px solid #dbe2ed;
}
.project-row { flex-wrap: wrap; }
.project-row span:first-child { flex: 1; }
.project-row span { overflow-wrap: anywhere; }
.project-row button { flex-shrink: 0; }
.task-filter, .project-filter { margin: 28px 0 16px; }
.task-row { justify-content: flex-start; flex-wrap: wrap; }
.task-row label { margin: 0; font-weight: 400; overflow-wrap: anywhere; }
.task-row input[type="checkbox"] { flex-shrink: 0; width: 18px; height: 18px; }
.rename-task { width: 100%; }
.rename-task label { margin-bottom: 8px; }
.task-priority label { margin-bottom: 8px; }
#back-to-projects { margin-bottom: 24px; }
#rename-project { margin-bottom: 28px; }
[role="alert"] { color: #a32020; }
[hidden] { display: none !important; }
@media (max-width: 600px) {
  main { margin: 20px 12px; padding: 24px 18px; }
  .form-controls { flex-direction: column; }
}
