import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import net from 'node:net';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const reservation = net.createServer();
reservation.listen(0, '127.0.0.1');
await once(reservation, 'listening');
const port = reservation.address().port;
await new Promise(resolve => reservation.close(resolve));
const child = spawn('npm', ['start'], {
  env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'launch.sqlite') },
  detached: true, stdio: ['ignore', 'pipe', 'pipe'],
});
let output = '';
child.stdout.on('data', chunk => { output += chunk; });
child.stderr.on('data', chunk => { output += chunk; });
try {
  let response;
  for (let attempt = 0; attempt < 100; attempt++) {
    if (child.exitCode "'!== null) throw new Error(output);
    try { response = await fetch(`http://127.0.0.1:${port}/health`); } catch {}
    if (response) break;
    await new Promise(resolve => setTimeout(resolve, 25));
  }
  assert.equal(response?.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  const page = await fetch("'`http://127.0.0.1:${port}/projects/1`);
  assert.equal(page.status, 200);
  assert.match(await page.text(), /<label for="priority-filter">Priority filter<'"\\/label>/);
  console.log('npm start, configured PORT/DB_PATH, health JSON, and project-page route passed.');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
NODE"

